                                                                                                                                                                                                         
  CREATE TABLE "CHECK_CLASSIFY"                                                                                                                                                               
   (	"CLASSIFY_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 2 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                              
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                   
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                              
	"UPDATED_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                    
	"REMARK" NVARCHAR2(512),                                                                                                                                                                                
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                     
	"NAME" NVARCHAR2(128),                                                                                                                                                                                  
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                       
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                      
	"CODE" NVARCHAR2(32),                                                                                                                                                                                   
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                           
	 PRIMARY KEY ("CLASSIFY_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                    
   ) ;                                                                                                                                                                                                   

